{"implementation":"def solve(case):
    segments = case['segments']
    budget = case['budget']
    n = len(segments)
    alloc = [seg['minimum'] for seg in segments]
    allocated = sum(alloc)
    total_cap = sum(seg['capacity'] for seg in segments)
    if budget < allocated or budget > total_cap:
        raise ValueError('Budget out of range')
    while allocated < budget:
        best_idx = -1
        best_score = -1.0
        for i, seg in enumerate(segments):
            if alloc[i] < seg['capacity']:
                score = seg['importance'] / (alloc[i] + 1)
                if score > best_score:
                    best_score = score
                    best_idx = i
        if best_idx == -1:
            break
        alloc[best_idx] += 1
        allocated += 1
    by_name = {seg['name']: alloc[i] for i, seg in enumerate(segments)}
    return {'allocations': alloc, 'by_name': by_name, 'total': sum(alloc)}"}
